(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fil"] = {"ui":{"skip":"Lumaktaw sa nilalaman","back":"← Bumalik sa AI-gile","lang.button":"Wika: {name}","lang.dialog":"Pumili ng wika","lang.search":"Maghanap ng wika","lang.none":"Walang wikang tumutugma","lang.notYet":"Hindi pa naisasalin ang {name}","theme.aria":"Magpalit ng tema: maliwanag, madilim o itim","theme.toLight":"Lumipat sa maliwanag na tema","theme.toDark":"Lumipat sa madilim na tema","theme.toBlack":"Lumipat sa itim na tema (tunay na itim, magaan sa OLED screen)","words.underline":"I-underline ang mga salitang ito sa page","words.underlineHelp":"I-hover o i-tap ang salitang may tuldok-tuldok para makita kung ano ang ibig sabihin nito.","words.col.todo":"Mga card na napili para sa ngayon: ito ang susunod na sisimulan ng team.","words.col.doing":"May AI na gumagawa sa card na ito ngayon.","words.col.review":"Tapos na ng isang AI ang gawain; chine-check ito ng isa pang AI bago makarating sa iyo.","words.col.verify":"Naghihintay sa iyo: subukan ito at sabihin kung gumagana.","words.col.team":"Ang mga tala o sagot mo, naghihintay na kunin ng team.","words.col.done":"Tapos na at tinanggap.","index.title":"AI-gile: ang AI dev team mo, sa iisang board","index.description":"Ang AI-gile ay kanban board para sa mga AI coding team. Nagtatrabaho sila habang natutulog ka; isang maikling tambak lang ang haharapin mo: mga desisyon, susubukan at aaprubahan.","hero.logoAlt":"Icon ng AI-gile board","hero.h1.html":"Ang AI dev team mo, sa iisang&nbsp;board.","hero.alpha":"🐣 Saradong pre-alpha","hero.alphaTitle":"Maaga pa at hindi pa tapos: salamat sa pagsubok!","hero.lede":"Gumagawa sila habang natutulog ka. Paggising mo, may isang maikling tambak: ilang tanong, ilang susubukan, isa o dalawang purple na diamond. I-click, aprubahan, balik sa kape mo.","dl.windows":"Windows app","dl.browser":"Gamitin sa browser","dl.messenger":"📱 Messenger para sa phone mo","dl.soon":"Malapit na","dl.notify":"🔔 Sabihan ako kapag bukas na","dl.notifySmall":"Alpha o beta","hero.secondary":"Agile, pero hindi kailanman nangangailangan ng stand-up na kape ang team. (Nagsta-stand-up pa rin naman sila.)","pitch.h2":"Ang AI-gile sa dami ng salitang gusto mo","pitch.lede":"Pumili ng haba, mula isang salita hanggang 144. Bawat haba ay sariling paglalarawan, isinulat para sa laki nito. I-drag ang slider o gamitin ang mga arrow key.","pitch.rangeLabel":"Haba sa bilang ng salita","pitch.dice":"🎲 ibang bersyon","pitch.words.one":"{n} salita","pitch.words.other":"{n} salita","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letra","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakter","count.line.html.one":"{n} card sa board ngayon","count.line.html.other":"{n} card sa board ngayon","people.humans.html.one":"👥 {n} tao","people.humans.html.other":"👥 {n} tao","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agent","people.working.html.one":"⚡ {n} ang nagtatrabaho ngayon","people.working.html.other":"⚡ {n} ang nagtatrabaho ngayon","pre.title":"AI-gile: may binubuo rito","pre.description":"May binubuo rito. Isang board kung saan binubuo ng mga AI team ang hinihingi mo, at tinuturuan ka habang ginagawa nila. Saradong pre-alpha muna kasama ang mga kaibigan.","pre.h1":"May binubuo rito. 🤫","pre.line":"Isang board kung saan binubuo ng mga AI team ang hinihingi mo, at tinuturuan ka habang ginagawa nila. Saradong pre-alpha muna kasama ang mga kaibigan.","pre.btn":"🔔 Sabihan ako kapag bukas na","pre.peek":"Sa likod ng salamin: ang totoong board, live. Bawat card ay isang makulay na bar.","pre.peekFake":"Sa likod ng salamin: ganito ang itsura ng board habang gumagana.","pre.night":"🌙 Ang bantay-gabi ang namamahala · 😴 nagpapahinga ang tao","features.aria":"Ano ang ginagawa nito","f.pile.h":"Isang tambak para sa iyo","f.pile.html":"Dito sa <b>Para sa iyo</b> nakalagay ang lahat ng naghihintay sa iyo, sa lahat ng project: mga tanong, mga susubukan, mga gawaing tao lang ang makakagawa. Sinasabi ng pila mo kung ano ang susunod at gaano ito katagal.","f.sleep.h":"Mga team na nagtatrabaho habang natutulog ka","f.sleep.p":"May lead at team ng mga AI agent ang bawat project. Mag-comment sa isang card at gigising ang team, gagawin ang trabaho, at ibabalik ito na may mga hakbang na masusundan kahit ng pagod na tao.","f.tester.h":"Unang sumusuri ang AI tester","f.tester.p":"Bago may makarating sa iyo, sinusundan ng tester ang mga hakbang sa kopya ng app at ipinapakita ang nakita niya, may screenshot. Tingnan nang mabilis ang mga pumasa at aprubahan sa isang click.","f.proof.h":"Patunay, hindi pangako","f.proof.p":"Ipinapakita ng bawat pasa kung ano ang nagbago: ang mga file, ang diff, ang mga screenshot. Hindi mo na kailangang buksan ang bawat app para malaman kung tapos na.","f.chat.h":"Makipag-chat sa mga lead mo","f.chat.p":"Riles na parang Discord: isang icon bawat project, purple na diamond para sa nangangailangan ng pansin mo. Magpadala ng idea sa lead; gagawin niya itong mga card at plano, may ✅ Go na button.","f.tidy.h":"Nag-aayos nang sarili","f.tidy.p":"Nagsasama ang magkakaugnay na card, naaayos ang magulong pamagat, at pinapanatiling magaan ng token check ang code. Mas kaunting pagpapalit-palit, mas kaunting iisipin.","f.private.h":"Sa iyo, sa computer mo","f.private.li1":"Tumatakbo ang board sa sarili mong makina at ikaw lang ang sinasagot.","f.private.li2":"End-to-end encrypted ang mga pribadong DM sa pagitan ng mga tao.","f.private.li3":"Walang account, walang tracker, walang cookie.","f.lang.h":"Sa wika mo","f.lang.p":"Mahigit 120 wika, mula Dutch, Welsh at Japanese hanggang pirate, Yoda at Klingon, may mabilis na balik sa English para sa mga teknikal na termino.","f.service.h":"Mula sa ideya tungo sa totoong service","f.service.p":"May nabuo ka gamit ang AI na ginagamit na ng mga tao? Markahan ito bilang service at tutulungan ka ng board na patakbuhin ito nang maayos: mga uptime check, pampublikong status page, mga incident na may write-up, mga pagbabagong kailangan ng Go, at mga backup na sinusuri araw-araw. Itinuturo ng Help ang bawat hakbang habang ginagawa mo.","msgr.h2":"AI-gile Messenger: ang team mo, nasa bulsa mo","msgr.p1":"Kausapin ang AI team mo nang hindi binubuksan ang board. Mag-chat sa mga project lead mo at sa mga kaibigan mo, at tingnan ang mga test step ng isang card at sagutin ang mga ito, lahat mula sa phone mo.","msgr.p2":"Para i-pair ito, i-scan ang QR code sa board mo. Unang beses? May friendly na demo chat na magtuturo sa iyo.","msgr.when":"Android muna, tapos isang web version para sa mga phone at iPhone.","msgr.who":"Ang project lead mo","msgr.b1":"Ready na ang fix sa dark mode. Gusto mo ba ang mga test step?","msgr.b2":"Oo, pakibigay!","msgr.b3":"1. Buksan ang Settings. 2. Piliin ang Dark. Mukha bang tama?","tl.aria":"Timeline mula sa unang usapan hanggang sa roadmap","tl.h2":"Mula sa unang chat hanggang sa susunod","tl.lede":"Totoong petsa at oras, sa sarili mong time zone. Pagkatapos ng ngayon, plano na ito, walang pinangakong petsa.","tl.today":"Ngayon","tl.planned":"planado","tl.doing":"ginagawa","tl.cards.one":"{n} card","tl.cards.other":"{n} card","join.h2":"Sumali ka","join.lede":"Ginagawa ang AI-gile ng isang balbas-saradong weirdo na may AuDHD at ilang laban sa mental health, kasama ang napakaraming matiyagang agent. Pribado pa ito sa ngayon, sa saradong alpha kasama ang mga kaibigan. Gusto mo bang sumubok kapag nagbukas na ito?","join.btn":"Magpahayag ng interes","join.small":"Mag-e-email lang kami, wala nang iba","footer.tag":"AI-gile. Walang tracker, walang cookie, walang stand-up na kape.","footer.licence":"Lisensya para sa negosyo","footer.status":"Status","footer.privacy":"Ano ang iniimbak namin","footer.thanks":"Mga call, salamat sa ChilledChat","form.sending":"Ipinapadala…","form.failed":"Hindi iyon umubra: subukan ulit mamaya.","form.offline":"Hindi maabot ang AI-gile: subukan ulit mamaya.","form.keep":"Ginagamit lang namin ito para sumagot sa iyo, saka namin ito buburahin. Walang tracker, walang cookie.","form.keepLink":"Ano ang iniimbak namin","interest.title":"AI-gile: sabihan ako kapag nagbukas ang alpha","interest.description":"Iwan ang email mo para malaman kapag nagbukas ang saradong alpha o beta ng AI-gile.","interest.h1":"🔔 Sabihan ako kapag bukas na","interest.lede":"Nasa saradong pre-alpha ang AI-gile. Iwan ang email mo at susulatan ka namin nang isang beses, kapag may lugar na para sa iyo.","interest.email":"Ang email mo","interest.which":"Aling pagsubok?","interest.alpha":"Saradong alpha: maaga, magaspang, maraming pagbabago","interest.beta":"Beta: mas matatag, mas huli","interest.both":"Alinman, kung ano ang mauna","interest.submit":"Ilagay mo ako sa listahan","interest.thanks":"Salamat! Nasa listahan ka na.","licence.title":"AI-gile: lisensya para sa negosyo","licence.description":"Ginagamit ang AI-gile sa negosyo mo? Mag-apply para sa libreng lisensya para sa negosyo.","licence.h1":"📜 Lisensya para sa negosyo","licence.lede":"Ginagamit ang AI-gile sa trabaho? Sabihin kung sino kayo at ano ang ginagawa ninyo. Kung nakakatulong ito sa kapwa, libre ang lisensya.","licence.company":"Kumpanya","licence.website":"Website","licence.what":"Ano ang ginagawa ninyo","licence.how":"Paano ito nakakatulong sa mundo","licence.email":"Email","licence.submit":"Mag-apply","licence.thanks":"Salamat! Sasagot kami sa email.","status.title":"Status ng AI-gile","status.h1":"Status ng AI-gile","status.quiet":"Tahimik ang lahat","status.intro":"Gumagana ba ang AI-gile ngayon? Tinitingnan ng page na ito ang website, ang pag-share ng board, ang mga tawag at ang download kada 5 minuto.","status.up":"Gumagana (sumagot sa loob ng {ms} ms)","status.slow":"Hindi sumagot sa huling check, sinusubukan ulit","status.down":"Down: hindi sumagot sa huling dalawang check","status.svc.web":"Website","status.svc.web.offers":"Ang site na ito: kung ano ang AI-gile, at ang interest form","status.svc.boards":"Pag-share ng board","status.svc.boards.offers":"Mga pampublikong board, mga mensahe sa pagitan ng magkakaibigan at mga imbitasyon","status.svc.calls":"Mga tawag","status.svc.calls.offers":"Boses, video at screen share sa AI-gile","status.svc.download":"Download","status.svc.download.offers":"Ang Windows installer at mga invite link","status.checking":"Sinusuri…","status.offline":"Hindi maabot ang status service ngayon (susubukan ulit)","status.updated":"na-update {ago}","status.justNow":"ngayon lang","status.min":"{n} min ang nakalipas","status.hours":"{n} oras ang nakalipas","status.days":"{n} araw ang nakalipas","privacy.title":"AI-gile: ano ang iniimbak namin","privacy.h1":"Ano ang iniimbak namin","privacy.lede":"Sa madaling salita: ang ipinapadala mo lang sa amin, at hindi nang matagal.","privacy.only":"Ang ipinapadala mo lang sa amin: ang tina-type mo sa isang form, gaya ng email mo. Wala nang iba tungkol sa iyo.","privacy.sealed":"Sine-seal ito para hindi ito mabasa ng server namin: sa browser mo bago ito umalis (sa mas lumang browser, sa sandaling dumating ito). Ang sarili lang naming board ang makakapagbukas nito.","privacy.server":"Binubura ito sa server sa sandaling makarating ito sa board namin. Anumang naroon pa rin pagkalipas ng 30 araw ay binubura rin.","privacy.board":"Iniimbak lang namin ito sa board namin hanggang makasagot kami sa iyo, saka namin ito buburahin doon din.","privacy.none":"Walang tracker, walang cookie, walang analytics.","privacy.local":"Ang wika mo at ang pinili mong light o dark ay nananatili sa sarili mong browser. Hindi kailanman ipinapadala sa amin ang mga ito.","privacy.ask":"Gusto mo bang mabura ito nang mas maaga? Sumagot ka lang sa email namin at sabihin mo.","live.h2":"Panoorin itong binubuo, live","live.caption":"Nakatago ang bawat card: makikita mo ang hugis ng gawain, hindi ang mga salita.","live.watching.one":"live: {n} ang nanonood","live.watching.other":"live: {n} ang nanonood","live.last.now":"Kalilipat lang ng huling card","live.last.min.one":"Nailipat ang huling card {n} min ang nakalipas","live.last.min.other":"Nailipat ang huling card {n} min ang nakalipas","live.last.hour.one":"Nailipat ang huling card {n} oras ang nakalipas","live.last.hour.other":"Nailipat ang huling card {n} oras ang nakalipas","live.last.day.one":"Nailipat ang huling card {n} araw ang nakalipas","live.last.day.other":"Nailipat ang huling card {n} araw ang nakalipas","live.offline":"Nagpapahinga muna ang live board. Balik ka ulit mamaya.","live.cols":"Backlog|Gagawin|Ginagawa|Chine-check ng team|Para sa iyo na i-test|Para sa team|Tapos na"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Naipasa."]},{"n":2,"texts":["Kanban, robot.","Agent, organisado.","Ginawang idea."]},{"n":3,"texts":["Kanban para sa robot.","Idea, ginagawang feature.","Libreng kanban ng agent."]},{"n":5,"texts":["Kanban board na pinapatakbo ng agent.","Ikaw ang nagsusulat, agent ang gumagawa.","Libre, lokal, sinubok, medyo kalokohan."]},{"n":8,"texts":["Libreng kanban board kung saan nagtatrabaho ang mga AI agent.","Magsulat ng idea. Gagawin ito ng agent. Ikaw ang aaprub.","Agile para sa isang tao at maraming matiyagang robot."]},{"n":13,"texts":["Kanban board sa computer mo kung saan kinukuha ng mga AI agent ang mga card.","Magsulat ng idea. Gagawin ito ng team ng agent. Susuriin ito ng tester.","Libre, walang account, walang tracker: isang board, ilang robot, at ikaw ang masusunod."]},{"n":21,"texts":["Ang AI-gile ay kanban board para makatrabaho ang mga AI coding agent. Sila ang kumukuha ng mga card; ikaw ang sumusubok at nag-aaprub.","Bawat project ay may lead at team ng mga AI agent. Mag-comment sa kahit anong card at magsisimulang magtrabaho ang team.","Libre at personal na to-do board na tumatakbo sa sarili mong computer. Mga robot ang gumagawa. Ikaw ang nagsasabi ng oo."]},{"n":34,"texts":["Ilalagay mo ang mga idea sa board. Gagawin ng team ng mga AI agent ang mga ito bilang gumaganang feature, susubukan, at ibabalik sa iyo na may mga hakbang na masusubukan mo. Walang matatapos hangga't hindi mo sinasabi.","Gawang-bahay na kanban board ang AI-gile na binuo ni Rich sa tulong ng napakaraming agent na ngayon ay pinamamahalaan nito. Libre ito, tumatakbo sa computer mo, at ibinabahagi sa mga kaibigan, hindi ibinebenta.","Isipin ang karaniwang kanban board, may mga column mula Backlog hanggang Tapos na, maliban na ang mga card ay kinukuha ng mga AI agent. Nag-uulat sila ng progreso, nagtatanong kapag naipit, at laging naghihintay ng pagsang-ayon mo."]},{"n":55,"texts":["Ang AI-gile ay kanban board na ang team ay binubuo ng mga AI agent. May lead ang bawat project na nagpaplano ng trabaho at mga katulong na gumagawa nito. Kapag handa na ang isang feature, sinusubukan ito ng AI tester at kumukuha ng screenshot, saka ito mapupunta sa tambak mo. Aprubahan ito, o mag-comment at gagawin nila ulit.","Nagsimula ito bilang paraan ng isang tao para masubaybayan ang maraming AI coding session nang sabay-sabay, at lumaki bilang tunay na board. Tumatakbo ito sa makina mo, walang account na kailangan, at walang tracker. Libre ito para sa mga kaibigan at sa mga curious. Hindi pa ito tapos, kaya asahan ang ilang gaspang at paminsan-minsang sorpresa.","Heto ang tapat na bersyon. Ikaw pa rin ang kailangang mag-isip ng mga idea, at ikaw pa rin ang kailangang tumingin sa mga resulta. Ang ginagawa ng AI-gile ay lahat ng nasa pagitan: pinapanatili nitong maayos ang mga card, ginigising ang tamang agent kapag nag-comment ka, ipinapakita kung ano mismo ang nagbago, at inilalagay ang lahat sa isang maikling tambak para sa iyo."]},{"n":89,"texts":["Ang AI-gile ay libreng kanban board na pinapatakbo mo sa sarili mong computer. Sa halip na mga tao, bawat project ay may team ng mga AI agent: isang lead na ginagawang mga card at plano ang mga idea mo, at mga katulong na kumukuha ng mga card ayon sa priyoridad. Kapag may nabuo na, sinusundan ng AI tester ang mga hakbang sa pagsubok at ipinapakita sa iyo ang nakita nito. Pagkatapos ay maghihintay ito sa isang tambak na tinatawag na Para sa iyo. Aprubahan mo, o mag-comment ka at susubukan ulit ng team. Walang makakarating sa Tapos na nang hindi ikaw ang nagpapasya.","Ilang feature na hindi mo marahil inaasahan. Pinupunan ng night watch ang column na Gagawin habang natutulog ka, at pumipili ito ng mga card na hindi nangangailangan ng sagot mo. Ipinapakita ng token counter kung gaano na ang nagamit ng mga agent ngayong araw at ngayong linggo, at sinasabihan sila ng No Token Mode na tumigil sa paggastos. Puwede kang magpadala ng mensahe sa mga kaibigan, at end-to-end encrypted ang mga pribadong mensahe. Nagsasalita ang board ng halos 120 wika, kasama ang Dutch, Flemish, pirate at Klingon. Wala ni isang sentimo ang babayaran dito, at walang nagtatangkang magbenta nito sa iyo.","Maliit at personal na proyekto ang AI-gile, hindi kumpanya. Gusto ni Rich na mabantayan ang ilang AI coding project nang hindi binubuksan ang bawat app para silipin ang mga ito, kaya gumawa sila ng board para rito ng mga agent, at ginamit nila ang board para buuin ang iba pang bahagi nito. Nasa saradong pre-alpha ito, ibig sabihin gumagana ito, kadalasan, para sa iilang kaibigan. Walang pricing page, walang newsletter at walang plano sa paglago. Kung mukha itong makakatulong, puwede kang humiling na subukan ito kapag mas nagbukas na ito."]},{"n":144,"texts":["Ang AI-gile ay kanban board para sa isang tao at maraming AI agent. Tumatakbo ito sa sarili mong computer at ganap na libre. Magdadagdag ka ng mga project, at bawat project ay magkakaroon ng lead at maliit na team. Makikipag-chat ka sa lead, medyo parang Discord, at ilalarawan mo ang isang idea; gagawin ito ng lead na mga card at plano, saka maghihintay na pindutin mo ang Go. Gagawin ng team ang mga card ayon sa priyoridad, gamit ang simpleng command line na ginawa para sa mga language model. Bago may bumalik sa iyo, susundan ng AI tester ang mga hakbang sa kopya ng app at maglalakip ng screenshot. Mapupunta sa tambak mo ang natapos na trabaho kasama ang mga nabagong file at ang diff. Aprubahan mo, o mag-iwan ka ng comment at gigising ang team at susubukan ulit. Ikaw lang ang puwedeng maglipat ng card sa Tapos na.","Isang araw kasama ang AI-gile, halos ganito. Sa gabi, mag-iiwan ka ng ilang comment: mali ang lugar ng buton na ito, dapat naka-sort ang listahang iyon, puwede bang magkaroon ng dark mode. Matutulog ka na. Babasahin ng mga agent ang mga comment, gagawin ang mga pagbabago, susubukan ang mga ito at ibabalik sa iyo. Kung maubusan ang Gagawin, pupunuin ito ng night watch mula sa backlog ng mga card na hindi nangangailangan ng sagot mo. Sa umaga, may isang maikling tambak: ilang tanong at ilang susubukan, bawat isa ay may mga hakbang na masusundan ng inaantok na tao at screenshot na gumagana ito. Magki-click ka, aaprubahan ang magaganda, at ibabalik ang iba. Ipinapakita ng token counter kung ano ang nagamit ng lahat ng ito, at nandiyan ang No Token Mode para sa mga mahigpit na linggo. Pagkatapos ay mag-aalmusal ka, na hindi pa kayang tulungan ng mga agent.","Una, kung ano ang hindi AI-gile. Hindi ito startup, hindi ito ibinebenta, at walang kumukuha ng data mo. Libreng board ito na tumatakbo sa computer mo, walang account, walang tracker at walang cookie. Ito naman ang AI-gile: isang maayos na lugar para makita ang bawat AI coding project nang sabay-sabay, may team ng mga agent na gumagawa ng mga card at ikaw ang nagpapasya. Pinagsasama nito ang magkakaugnay na card, inaayos ang magulong pamagat, at binabantayan kung nananatiling magaan ang code. Nagsasalita ito ng halos 120 wika, mula Dutch at Flemish hanggang pirate at Klingon. Puwedeng magpadala ng mensahe ang magkakaibigan sa isa't isa, pribado at naka-encrypt. Binuo ito ni Rich at ng napakaraming matiyagang agent, kadalasan sa pamamagitan ng paggamit dito mismo. Nasa saradong pre-alpha ito, kaya may gaspang pa sa ilang bahagi. Kung mukhang masaya, magtanong nang magalang at baka makapasok ka nang maaga."]}],"quips":{"1":"Isang salita. Matapang. Baka sobra pa.","3":"Tatlong salita. Mas tapat na kaysa sa karamihan ng product page.","8":"Walong salita. Mas maikli pa sa isang stand-up.","21":"Nga pala, story point ang mga haba. Siyempre naman.","55":"Limampu't limang salita. Dalawang card ang natapos habang binabasa mo iyan.","144":"Iyan ang mahaba. Walang 233. Natulog na ang mga agent."}},"timeline":{"first-idea.name":"Ang unang idea","first-idea.line":"Ang pinakaunang usapan, bago pa magkaroon ng anumang code.","first-board.name":"Unang board","first-board.line":"Board na sinusubaybayan ang sarili nitong pagbuo: mga card, column, drag and drop, mga project.","team-roles.name":"Team at mga role","team-roles.line":"Mga profile ng agent, template ng team, mga space at kung sino ang gumagawa ng ano.","install.name":"Pag-install at mga release","install.line":"Zip na kayang i-install ng kaibigan, self-update, mga channel at pag-roll back.","usage-saver.name":"Pagtitipid sa gamit","usage-saver.line":"Sukatin ang gastos ng bawat takbo, panatilihing magaan ang code, protektahan ang limit mo.","friends.name":"Mga kaibigan at pagbabahagi","friends.line":"Mga pribadong DM, ginulong relay, mga imbitasyon, mga role at pinagsasaluhang project.","languages.name":"Mga wika","languages.line":"Bawat teksto sa screen ay nasa language file, Dutch at Flemish muna.","ai-tester.name":"AI tester","ai-tester.line":"Sinusuri muna ng tester ang bawat pasa at ipinapakita ang nakita niya.","website.name":"Ang website","website.line":"Ang aigile.lol, ang teaser at ang timeline na ito.","streaming.name":"Chat at streaming","streaming.line":"Discord, Twitch, OBS, streamer mode, mga GIF at emoji.","no-ai.name":"Edisyong walang AI","no-ai.line":"Board para sa mga nagko-code nang walang AI, at mga pampublikong board.","night-watch.name":"Night watch","night-watch.line":"Isang bantay at Scrum Master ang nagpapanatili sa mga team sa gawain habang natutulog ka.","p-more.name":"Lahat ng iba pa","p-more.line":"Mas maliliit na idea na naghihintay pa ng turn nila.","p-android.name":"Telepono at Android","p-android.line":"Maabot ang board mo mula sa telepono, tapos native na Android app.","p-release.name":"Alpha at higit pa","p-release.line":"Saradong alpha, ang live na site, tapos beta.","p-languages.name":"Higit pang wika","p-languages.line":"130 wika, at immersion mode para sa mga nag-aaral.","p-engines.name":"Higit pang AI engine","p-engines.line":"Pumili ng Claude, Codex, Gemini, Copilot o Cursor para sa bawat agent.","p-pro.name":"Propesyonal na gawi","p-pro.line":"Mga risk label, merge gate, mga incident card at mga guard rail.","p-self.name":"Pag-aalaga sa iyo","p-self.line":"Tired mode, mga paalala sa self-care at 4:20.","p-servers.name":"Mga server at paglaki","p-servers.line":"Pangkalahatang setting ng server, mga role at pagpaplano para sa paglago.","p-livestream.name":"Mga dagdag sa streaming","p-livestream.line":"Twitch chat, custom na emoji at pampublikong live view."},"words":{"button":"📖 Mga teknikal na termino","h":"📖 Mga salitang ipinaliwanag","intro":"Ang mga salitang makikita mo sa AI-gile, sa simpleng pananalita: pagbuo nito, ligtas na pagbabago nito, pagpapanatiling gumagana nito para sa mga gumagamit, at pagtatrabaho bilang team kasama ang AI.","search":"Maghanap ng salita…","none":"Walang salitang tumutugma.","close":"Isara","count":{"one":"{count} salita","other":"{count} salita"},"groups":[{"id":"build","name":"🛠️ Pagbuo"},{"id":"change","name":"🔀 Ligtas na pagbabago"},{"id":"run","name":"🛎️ Pagpapatakbo ng service"},{"id":"team","name":"🤝 Pagtatrabaho bilang team (at kasama ang AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Ang folder ng code ng project at ang buong history ng mga commit nito, na karaniwang nasa GitHub din.","also":["repo","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Hiwalay na linya ng trabaho sa code, para makapagbago nang hindi ginagalaw ang pangunahing bersyon.","also":["branch","mga branch"]},{"id":"commit","g":"build","word":"Commit","text":"Naka-save na snapshot ng code, na may maikling note kung ano ang nagbago. Puwede kang laging bumalik sa isa.","also":["commit","mga commit"]},{"id":"push","g":"build","word":"Push","text":"Pagpapadala ng mga naka-save na snapshot (commit) mula sa computer na ito pataas sa GitHub, para ma-back up at maibahagi."},{"id":"merge","g":"build","word":"Merge","text":"Pagsasama ng mga pagbabago ng isang branch pabalik sa pangunahing bersyon."},{"id":"pr","g":"build","word":"Pull request","text":"Paghiling na i-check ang mga pagbabago ng isang branch at i-merge sa pangunahing bersyon.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Pag-aayos ng code nang hindi binabago ang ginagawa nito: mas maliliit na file, mas malilinaw na pangalan, mas kaunting pag-uulit."},{"id":"bug","g":"build","word":"Bug","text":"Isang bagay na hindi gumagana nang tama.","also":["bug","mga bug"]},{"id":"test","g":"build","word":"Test","text":"Pagsubok sa natapos na trabaho para tiyaking ginagawa nito ang hiniling, bago mo ito tanggapin.","also":["test","mga test"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Maikli para sa quality assurance: ang mga awtomatikong check na tumatakbo bago mag-live ang kahit ano. Kapag pula ang QA, may pumalya, at hindi ito puwedeng mag-live hangga't hindi naaayos.","also":["quality checks","quality assurance","pagsusuri ng kalidad"]},{"id":"deploy","g":"change","word":"Deploy","text":"Pagpapa-live ng bagong bersyon, halimbawa sa server na ginagamit ng mga tao."},{"id":"release","g":"change","word":"Release","text":"Isang bungkos ng tapos na trabaho na may pangalan at sabay-sabay na nagla-live, kasama ang maikling notes kung ano ang nagbago. Ang 🚀 Releases ang sumusulat ng notes mula sa mga tapos na card.","also":["releases","mga release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Pagbalik sa huling bersyong gumagana kapag nagkaproblema ang bago. Sa AI-gile, gumagawa ito ng checklist mula sa mga hakbang sa pag-undo na nakasulat sa bawat pagbabago.","also":["roll back","i-rollback","na-rollback"]},{"id":"live","g":"change","word":"Live","text":"Ang totoong bersyon na ginagamit ng mga tao, hindi ang kopya para sa pagsubok. Tinatawag din ito ng mga developer na production.","also":["production","naka-live","mag-live"],"noTip":1},{"id":"change","g":"change","word":"Pagbabago","text":"Isang planadong pagbabago sa bagay na inaasahan ng mga tao, na isinusulat muna: ano, bakit, ang panganib, kailan, at paano ito ia-undo. Magsimula ng isa sa 🔀 Mag-raise ng pagbabago.","also":["mga pagbabago","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Panganib","text":"Isang bagay na puwedeng magkamali, na may score batay sa kung gaano ito kalamang at gaano kalala. Itinatabi ng ⚠️ Mga panganib ang lahat sa iisang listahan, pinakamataas na score muna, bawat isa may petsa kung kailan titingnan ulit.","also":["mga panganib","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"Ang mga oras kung kailan puwedeng mag-live ang mga pagbabago, gaya ng tahimik na Martes ng gabi. Sa labas ng window, hindi matatapos ang isang change card, maliban kung emergency.","also":["mga change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"Mabilis na botohan bago mag-live ang isang pagbabago: bawat taong kailangang mag-approve ay nagsasabi ng Go o No go. Tutuloy lang ito kapag sang-ayon sila.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Paghihintay ng oo bago magsimula ang trabaho. Ang card na ginawa ng isang kaibigan, o isang pagbabago, ay naghihintay sa ✅ Mga approval hanggang i-approve o i-decline mo ito.","also":["mga approval","approvals","pag-apruba"]},{"id":"quiettime","g":"change","word":"Tahimik na oras","text":"Isang yugto ng oras, gaya ng stream, demo o gabi, kung kailan walang magla-live. Tuloy ang trabaho at testing ng mga team, pero ang pag-live ay maghihintay hanggang matapos ito. Sa ibang lugar, tinatawag itong change freeze.","also":["mga tahimik na oras","quiet time","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Isang bagay na binuo mo na inaasahan ng mga tao, gaya ng website o app, na inaalagaan para patuloy na gumana. I-tick ang “Ang project na ito ay isang service” at sabihin kung ano ang inaalok nito, sino ang gumagamit at sino ang on-call.","also":["services","mga service","serbisyo"]},{"id":"uptime","g":"run","word":"Uptime check","text":"Isang awtomatikong check, bawat ilang minuto, na sumasagot pa ang service mo. Kapag pumalya ito nang ilang beses na sunod-sunod, kusang magbubukas ang AI-gile ng incident card.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"Isang pampublikong page na nagpapakita kung gumagana ang isang service (berde, orange o pula) kasama ang pinakabagong update, para ang mga gumagamit ay makatingin na lang sa halip na magtanong.","also":["status pages"]},{"id":"desk","g":"run","word":"Service desk","text":"Dito pumapasok ang mga tanong at report mula sa mga taong gumagamit ng service mo. Inuuri ng AI-gile ang bawat isa bilang request, incident o idea, at sinasabi nito kapag mukhang naireport na dati.","also":["service desks","desk","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Service request","text":"May humihingi ng karaniwang bagay, gaya ng bagong account o kaunting tulong, sa halip na mag-report na may sira. Naghihintay ito ng turno nito; nauuna ang incident.","also":["service requests"]},{"id":"incident","g":"run","word":"Incident","text":"Isang bagay na sira ngayon mismo para sa mga gumagamit nito, gaya ng website na down. Ang 🔥 incident card ay nauuna sa pila: ang pagpapagana ulit nito ang pinakauna.","also":["incidents","mga incident","insidente"]},{"id":"major","g":"run","word":"Major incident","text":"Isang malaking incident: maraming taong apektado, o nanganganib ang pera o data. Isang button ang naglalagay sa lahat ng team dito (swarm), gumigising sa kung sino ang on-call, at humihingi ng status update bawat 30 minuto.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Ikaw ang sasagot kapag may nasira, kahit gabi. Bawat service ay may on-call na miyembro ng team na unang ginigising para sa mga incident nito.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"Kung gaano katagal puwedeng maghintay ang isang card ng unang sagot, halimbawa isang oras para sa incident. Pagkatapos noon, nagkakaroon ito ng pulang orasan, para walang tahimik na makalimutan. Tinatawag din itong response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Isang maikling pagbabalik-tanaw pagkatapos ng incident: ano ang nangyari, ano ang nakatulong at ano ang babaguhin, nang walang sinisisi. Hindi maisasara ang isang incident nang wala nito.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problema","text":"Ang nakatagong sanhi sa likod ng isa o higit pang incident. Pinagsasama ng 🧩 problem card ang mga incident na paulit-ulit na bumabalik, para mahanap ang sanhi at maayos ito nang tuluyan.","also":["mga problema","problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"Ang tunay na dahilan kung bakit may nasira, hindi lang ang nakita mong nagkamali. Ayusin ang root cause at hindi na babalik ang incident.","also":["root causes","ugat ng problema"]},{"id":"workaround","g":"run","word":"Workaround","text":"Paraan para patuloy na gumana ang mga bagay habang hindi pa handa ang totoong ayos, gaya ng pag-restart ng isang bagay kapag na-stuck ito. Nakasulat ito sa problem card para wala nang kailangang mag-isip nito ulit.","also":["workarounds","pansamantalang solusyon"]},{"id":"knownerror","g":"run","word":"Known error","text":"Isang problemang naiintindihan na ang sanhi at may workaround, pero hindi pa naaayos. Inililista ito ng 🧩 Known errors, para lahat ay gumamit ng workaround sa halip na maghukay ulit.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Sunud-sunod na instruksyon para ayusin ang kilalang uri ng problema, para pareho at mabilis itong magawa sa bawat pagkakataon. Pagkatapos ng malaking incident, puwedeng magmungkahi ang team ng isa para i-OK mo.","also":["runbooks"]},{"id":"ci","g":"run","word":"Configuration item","text":"Isang bagay na inaasahan ng service mo, gaya ng server, domain, certificate, key o supplier. Inililista ng 🗂️ Configuration items ang mga ito bawat service, para makita mo kung ano ang naaapektuhan ng isang incident at ano ang kailangang i-renew o i-back up.","also":["configuration items","CI"]},{"id":"expiry","g":"run","word":"Expiry date","text":"Binabantayan ng AI-gile ang mga petsa gaya ng kung kailan mag-e-expire ang isang certificate o domain. Sa loob ng 30 araw bago ang petsa, gagawa ito ng isang card para i-renew ito, para walang biglang tumigil gumana.","also":["expiry dates","expiry","petsa ng pag-expire","expiry watch"]},{"id":"backup","g":"run","word":"Backup","text":"Isang naka-save na kopya ng data mo mula dati, na mababalikan kung may mawala o masira. Gumagawa ang AI-gile ng backup ng mga board mo araw-araw.","also":["backups","back-up","mga backup"]},{"id":"restore","g":"run","word":"Restore","text":"Pagbabalik ng data mula sa backup. Talagang may silbi lang ang backup kapag alam mong kaya itong i-restore, kaya sulit na subukan ito paminsan-minsan.","also":["i-restore","na-restore","ibalik"]},{"id":"svcreview","g":"run","word":"Service review","text":"Pagbabalik-tanaw sa isang buwan ng isang service: mga incident na binuksan at naayos, gaano kabilis nakakuha ng sagot ang mga tao, uptime at mga token na nagamit. Ipinapakita ito ng Buwanang review para sa bawat service.","also":["service reviews","buwanang review","monthly review"]},{"id":"accessreview","g":"run","word":"Access review","text":"Pagsuri kada 90 araw kung sino pa ang makakapasok: share links, roles ng mga kaibigan at mga naka-keep na secret. I-keep o aalisin mo ang bawat isa, para hindi maiwan ang lumang access.","also":["access reviews"]},{"id":"improvements","g":"run","word":"Improvement list","text":"Lahat ng napagpasyahan ng team na pagbutihin, nasa iisang lugar: retro suggestions, review actions at problem fixes, bawat isa may status. Makikita ito sa 📈 Improvements.","also":["improvement lists","improvements"]},{"id":"tokencap","g":"run","word":"Token cap","text":"Buwanang limit sa mga token na puwedeng gamitin ng mga agent ng isang service. Sa 80% may babala ka; sa 100% maghihintay ang background work nila hanggang sa susunod na buwan o hanggang itaas mo ang cap.","also":["token caps","buwanang token cap"]},{"id":"backlog","g":"team","word":"Backlog","text":"Mga idea at trabahong hindi pa naipaplano. Walang gagawin dito hangga't hindi ito nalilipat sa Gagawin."},{"id":"sprint","g":"team","word":"Sprint","text":"Maikling yugto ng trabaho (madalas isa o dalawang linggo) na may napagkasunduang set ng mga card na tatapusin.","also":["sprint","mga sprint"]},{"id":"standup","g":"team","word":"Stand-up","text":"Mabilis na check-in: ano ang ginawa ng bawat miyembro, ano ang susunod nilang gagawin, at ano ang humahadlang sa kanila.","also":["standup","stand-up","mga stand-up"]},{"id":"kanban","g":"team","word":"Kanban","text":"Board na may mga column (Gagawin, Ginagawa, Tapos na) kung saan lumilipat pakanan ang mga card habang umuusad ang trabaho."},{"id":"wip","g":"team","word":"WIP limit","text":"Work in progress: ang pinakamaraming card na dapat hawakan ng isang column, para tapusin muna ng team ang mga bagay bago magsimula ng iba.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"Ang maikling checklist ng team kung ano ang ibig sabihin ng “tapos”, gaya ng na-test at naipaliwanag, bago iabot sa iyo ang isang card. Ang kakambal nito, ang Definition of Ready, ang nagsasabi kung kailan malinaw na ang card para simulan.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"Ang mga tapos na card na naghihintay na subukan mo, isa-isa. Tanggapin ang isa o ibalik ito na may note, at lalabas ang susunod.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"Pagbabalik-tanaw sa paraan ng pagtatrabaho ng team, para magkasundo sa isang bagay na gagawing mas mahusay. Sa AI-gile, ang retro ay nagmumungkahi ng pagbabago sa ways of working ng team, at ikaw ang magsasabi ng Go o Hindi pa.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"Isa pang pares ng mata: may isa pang AI na sumusuri sa trabaho ng bawat card bago ito umabot sa iyo, para mas kaunting mali ang makalusot.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Lahat ng kamay, tulong-tulong: iniiwan ng bawat team ang ibang trabaho para tumulong sa isang urgent na project hanggang maayos ito. Naghihintay muna ang ibang project.","also":["swarming","i-swarm"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Ang nagpapatuloy sa daloy ng trabaho: napapansin ang mga stuck na card, kinukulit ang mga team at ipinapaalala sa iyo kung ano ang naghihintay. Sa AI-gile, ang Lead Scrum Master ang gumagawa nito sa lahat ng project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI na kusang gumagawa ng isang task: binabasa ang code, gumagawa ng pagbabago, nagpapatakbo ng check, at nag-uulat pabalik.","also":["agent","mga agent"]},{"id":"token","g":"team","word":"Token","text":"Ang yunit na ginagamit sa pagbilang ng paggamit ng AI: halos ilang letra ng text na binabasa o isinusulat. Mas kaunting token, mas maraming natitira sa plan mo.","also":["token","mga token"]},{"id":"hook","g":"team","word":"Hook","text":"Maliit na command na kusang tumatakbo sa takdang sandali, hal. kapag nagsimula ang AI session, para marinig ng team ang mga comment mo.","also":["hook","mga hook"]}]}};
